<?php require_once __DIR__ . '/includes/ai_service.php';
$caseCode = $_GET['case'] ?? $_POST['case_code'] ?? ''; $case = db_fetch('SELECT pc.*, p.full_name,p.phone,p.whatsapp FROM patient_cases pc JOIN patients p ON p.id=pc.patient_id WHERE pc.case_code=?', [$caseCode]); if(!$case){ public_header('Case not found'); echo '<div class="container py-5">'.empty_state('Case not found.').'</div>'; public_footer(); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $msg=trim((string)($_POST['message']??'')); if($msg!=='') db_execute('INSERT INTO chat_messages (case_id,sender_type,message,metadata_json,created_at) VALUES (?,?,?,?,NOW())', [$case['id'],'patient',$msg,'{}']); $messages=db_fetch_all('SELECT sender_type,message,created_at FROM chat_messages WHERE case_id=? ORDER BY id ASC', [$case['id']]); try{ $res=call_openrouter($case,$messages); $data=$res['data']; $reply=$data['emergency_flag'] ? $data['emergency_message'] : ($data['needs_more_questions'] ? implode("\n", $data['questions'] ?: ['Please share more details about your symptoms.']) : 'Your AI-prepared case summary is ready for specialist doctor verification.'); db_execute('INSERT INTO chat_messages (case_id,sender_type,message,metadata_json,created_at) VALUES (?,?,?,?,NOW())', [$case['id'],'ai',$reply,json_encode_safe($data)]); if(!$data['needs_more_questions'] || $data['emergency_flag']) { save_ai_report((int)$case['id'],$data,$res['raw'],$res['tokens']); db_execute('UPDATE patient_cases SET ai_status=?, emergency_flag=?, status=? WHERE id=?', ['completed',$data['emergency_flag']?1:0,$data['emergency_flag']?'emergency_flagged':'pending_doctor_review',$case['id']]); } } catch(Throwable $e){ error_log($e->getMessage()); db_execute('UPDATE patient_cases SET ai_status="failed", status="manual_review_required" WHERE id=?', [$case['id']]); db_execute('INSERT INTO chat_messages (case_id,sender_type,message,metadata_json,created_at) VALUES (?,?,?,?,NOW())', [$case['id'],'system','Your case has been received. Our specialist team will review it and contact you.',json_encode_safe(['error'=>'ai_failed'])]); } redirect('chat.php?case='.urlencode($caseCode)); }
$messages=db_fetch_all('SELECT * FROM chat_messages WHERE case_id=? ORDER BY id ASC', [$case['id']]); $report=db_fetch('SELECT * FROM ai_case_reports WHERE case_id=? ORDER BY id DESC LIMIT 1', [$case['id']]); public_header('Chat'); ?>
<section class="py-4"><div class="container chat-wrap"><div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Doctor-style AI Chat</h1><p class="mb-0 text-muted">Case ID: <strong><?= e($caseCode) ?></strong></p></div><a class="btn btn-outline-success" href="track-case.php">Track</a></div><div class="chat-box mb-3"><?php foreach($messages as $m): ?><div class="bubble <?= $m['sender_type']==='patient'?'patient':'ai' ?>"><small class="text-muted"><?= e(ucfirst($m['sender_type'])) ?></small><br><?= nl2br(e($m['message'])) ?></div><?php endforeach; ?></div><?php if($case['status']==='manual_review_required'): ?><div class="alert alert-info">Your case has been received. Our specialist team will review it and contact you.</div><?php endif; ?><?php if($report): ?><div class="card soft-card mb-3"><div class="card-body"><h4>AI-prepared draft ready</h4><p>Doctor review required before any medicine delivery.</p><a href="order-request.php?case=<?= e($caseCode) ?>" class="btn btn-teal">Request Medicine Order</a></div></div><?php endif; ?><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="case_code" value="<?= e($caseCode) ?>"><textarea name="message" class="form-control" placeholder="Reply in English, Urdu, or Roman Urdu" required></textarea><button class="btn btn-teal">Send</button></form></div></section><?php public_footer(); ?>
